import { create } from 'zustand';
import { devtools } from 'zustand/middleware';
import { shallow } from 'zustand/shallow';

// Global application state
interface AppState {
  // UI state
  sidebarOpen: boolean;
  theme: 'light' | 'dark' | 'system';

  // Error state
  globalError: string | null;

  // Loading state
  isLoading: boolean;

  // Actions
  setSidebarOpen: (open: boolean) => void;
  setTheme: (theme: 'light' | 'dark' | 'system') => void;
  setGlobalError: (error: string | null) => void;
  setLoading: (loading: boolean) => void;
  clearError: () => void;
}

// Create global state store
export const useAppStore = create<AppState>()(
  devtools(
    (set) => ({
      // Initial state
      sidebarOpen: false,
      theme: 'system',
      globalError: null,
      isLoading: false,

      // Actions
      setSidebarOpen: (open) => set({ sidebarOpen: open }),
      setTheme: (theme) => set({ theme }),
      setGlobalError: (error) => set({ globalError: error }),
      setLoading: (loading) => set({ isLoading: loading }),
      clearError: () => set({ globalError: null }),
    }),
    {
      name: 'app-store',
    }
  )
);

// Selectors for better performance
export const useSidebarOpen = () => useAppStore((state) => state.sidebarOpen);
export const useTheme = () => useAppStore((state) => state.theme);
export const useGlobalError = () => useAppStore((state) => state.globalError);
export const useIsLoading = () => useAppStore((state) => state.isLoading);

// Actions with shallow comparison to prevent infinite loops
export const useAppActions = () => useAppStore(
  (state) => ({
    setSidebarOpen: state.setSidebarOpen,
    setTheme: state.setTheme,
    setGlobalError: state.setGlobalError,
    setLoading: state.setLoading,
    clearError: state.clearError,
  }),
  shallow
);
