import {
  validateApiEnvelope,
  validateHealthResponse,
  validateModelsResponse,
  validateRunsResponse,
  validateRunDetailResponse,
  validateStartRunRequest,
  validateStartRunResponse,
  validateGraphResponse,
  validateClaimsResponse,
  validateEntitiesResponse,
  validateErrorResponse,
  type HealthResponse,
  type ModelsResponse,
  type RunsResponse,
  type RunDetailResponse,
  type StartRunRequest,
  type StartRunResponse,
  type GraphResponse,
  type ClaimsResponse,
  type EntitiesResponse,
  type ErrorResponse
} from './schemas';

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8050';

class ApiError extends Error {
  constructor(
    message: string,
    public status: number,
    public code?: number
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

async function apiRequest<T>(
  endpoint: string,
  options: RequestInit = {}
): Promise<T> {
  const url = `${API_BASE_URL}${endpoint}`;
  const config: RequestInit = {
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
    ...options,
  };

  try {
    const response = await fetch(url, config);
    const data = await response.json();

    // Validate the API envelope
    const envelope = validateApiEnvelope(data);

    if (envelope.status === 'error') {
      const errorData = validateErrorResponse(data);
      throw new ApiError(
        errorData.error.message,
        response.status,
        errorData.error.code
      );
    }

    return data as T;
  } catch (error) {
    if (error instanceof ApiError) {
      throw error;
    }
    if (error instanceof Error) {
      throw new ApiError(error.message, 0);
    }
    throw new ApiError('Unknown error occurred', 0);
  }
}

// Health API
export async function getHealth(): Promise<HealthResponse> {
  const data = await apiRequest<HealthResponse>('/api/health/full');
  return validateHealthResponse(data);
}

// Models API
export async function getModels(): Promise<ModelsResponse> {
  const data = await apiRequest<ModelsResponse>('/api/models');
  return validateModelsResponse(data);
}

// Runs API
export async function getRuns(): Promise<RunsResponse> {
  const data = await apiRequest<RunsResponse>('/api/runs');
  return validateRunsResponse(data);
}

export async function getRun(runId: string): Promise<RunDetailResponse> {
  const data = await apiRequest<RunDetailResponse>(`/api/runs/${runId}`);
  return validateRunDetailResponse(data);
}

export async function getRunCorpus(runId: string): Promise<RunDetailResponse> {
  const data = await apiRequest<RunDetailResponse>(`/api/runs/${runId}/corpus`);
  return validateRunDetailResponse(data);
}

export async function startRun(request: StartRunRequest): Promise<StartRunResponse> {
  // Validate the request
  const validatedRequest = validateStartRunRequest(request);
  
  const data = await apiRequest<StartRunResponse>('/api/runs/youtube/start', {
    method: 'POST',
    body: JSON.stringify(validatedRequest),
  });
  return validateStartRunResponse(data);
}

// Graph API
export async function getGraph(runId: string): Promise<GraphResponse> {
  const data = await apiRequest<GraphResponse>(`/api/graph/${runId}`);
  return validateGraphResponse(data);
}

// Claims API
export async function getClaims(
  runId: string,
  page: number = 1,
  perPage: number = 20
): Promise<ClaimsResponse> {
  const data = await apiRequest<ClaimsResponse>(
    `/api/runs/${runId}/claims?page=${page}&per_page=${perPage}`
  );
  return validateClaimsResponse(data);
}

// Entities API
export async function getEntities(
  runId: string,
  page: number = 1,
  perPage: number = 20
): Promise<EntitiesResponse> {
  const data = await apiRequest<EntitiesResponse>(
    `/api/runs/${runId}/entities?page=${page}&per_page=${perPage}`
  );
  return validateEntitiesResponse(data);
}

// Tools API
export async function getTools(): Promise<unknown> {
  return apiRequest('/api/tools');
}

export { ApiError };
export type { StartRunRequest };
